async () => {
  const W = 1440;
  document.getElementById('__vp_wrap')?.remove();
  const wrap = document.createElement('div');
  wrap.id = '__vp_wrap';
  wrap.style.cssText = 'position:fixed;inset:0;z-index:2147483647;background:#0f172a;overflow:hidden;';
  const iframe = document.createElement('iframe');
  iframe.id = '__vp_iframe';
  iframe.style.cssText = `width:${W}px;height:900px;border:0;display:block;background:#0f172a;`;
  iframe.src = location.origin + '/';
  wrap.appendChild(iframe);
  document.body.appendChild(wrap);
  await new Promise((res, rej) => { iframe.addEventListener('load', res, { once: true }); setTimeout(() => rej(new Error('iframe load timeout')), 25000); });
  const doc = iframe.contentDocument;
  const win = iframe.contentWindow;
  const t0 = Date.now();
  await new Promise((res, rej) => {
    const tick = () => {
      if (doc.querySelector('header') && doc.querySelector('[data-testid="datasource-select"]')) return res(null);
      if (Date.now() - t0 > 20000) return rej(new Error('render timeout header=' + !!doc.querySelector('header') + ' ds=' + !!doc.querySelector('[data-testid="datasource-select"]') + ' readyState=' + doc.readyState));
      setTimeout(tick, 250);
    };
    tick();
  });
  await new Promise(r => setTimeout(r, 1200));

  const header = doc.querySelector('header');
  const headerRect = header.getBoundingClientRect();
  const cs = (el) => win.getComputedStyle(el);
  const isVisible = (el) => { if (!el) return false; const c = cs(el); return c.display !== 'none' && c.visibility !== 'hidden' && el.getClientRects().length > 0; };
  const lineInfo = (el) => {
    const range = doc.createRange();
    range.selectNodeContents(el);
    const rects = Array.from(range.getClientRects());
    const tops = [...new Set(rects.map(r => Math.round(r.top)))].sort((a, b) => a - b);
    const groups = [];
    tops.forEach(t => { if (!groups.length || t - groups[groups.length - 1] > 2) groups.push(t); });
    return { lines: groups.length, textRects: rects.length };
  };
  const q = (sel, root) => (root || header).querySelector(sel);
  const qa = (sel, root) => [...(root || header).querySelectorAll(sel)];
  const info = (key, el, { text = false } = {}) => {
    if (!el) return { key, found: false, visible: false };
    const vis = isVisible(el);
    const r = el.getBoundingClientRect();
    const out = {
      key, found: true, visible: vis, display: cs(el).display,
      rect: { left: +r.left.toFixed(1), right: +r.right.toFixed(1), w: +r.width.toFixed(1), h: +r.height.toFixed(1) },
      withinHeader: +( (headerRect.right - r.right).toFixed(1) ) >= -0.5 && r.left >= headerRect.left - 0.5,
    };
    const t = (el.textContent || '').trim();
    if (t) out.text = t.slice(0, 50);
    if (vis && text) Object.assign(out, lineInfo(el));
    return out;
  };

  const dsSelect = q('[data-testid="datasource-select"]');
  const dsSwitcher = dsSelect ? dsSelect.parentElement : null;
  const connected = dsSwitcher ? qa('div', dsSwitcher).find(d => d.textContent.includes('已连接')) : null;
  const amountSelect = q('[data-testid="global-amount-unit-select"]');
  const reportBtn = q('button[title="自动生成报表"]');
  const dsBtn = q('button[title="接入数据源"]');
  const userChip = qa('div').find(d => d.className.includes('border-l'));
  const userInfo = userChip ? qa('div', userChip).find(d => d.className.includes('lg:block')) : null;
  const roleBadge = userInfo ? q('span', userInfo) : null;

  const items = [
    info('logo图标', qa('div')[1] ? qa('div')[1] : null),
    info('标题h1', q('h1'), { text: true }),
    info('版本徽章(lg)', qa('span').find(s => s.textContent.includes('NL2SQL Pro')), { text: true }),
    info('副标题(sm)', q('p'), { text: true }),
    info('数据源切换器(md)', dsSwitcher),
    info('当前数据源label', dsSwitcher ? qa('span', dsSwitcher).find(s => s.textContent.includes('当前数据源')) : null, { text: true }),
    info('数据源select', dsSelect),
    info('已连接(2xl)', connected, { text: true }),
    info('金额单位容器(lg)', amountSelect ? amountSelect.parentElement : null),
    info('金额单位select', amountSelect),
    info('自动生成报表按钮', reportBtn),
    info('报表按钮文字(xl)', reportBtn ? q('span', reportBtn) : null, { text: true }),
    info('接入数据源按钮(sm)', dsBtn),
    info('数据源按钮文字(xl)', dsBtn ? q('span', dsBtn) : null, { text: true }),
    info('主题按钮', qa('button').find(b => (b.title || '').includes('主题'))),
    info('帮助按钮', q('button[title="帮助 · 使用指南"]')),
    info('用户区', userChip),
    info('用户头像', userChip ? q('.rounded-full', userChip) : null),
    info('用户信息文字(lg)', userInfo, { text: true }),
    info('角色徽章', roleBadge, { text: true }),
    info('退出按钮', q('button[title="退出登录"]')),
    info('申请权限按钮(条件)', qa('button').find(b => (b.title || '').includes('申请访问权限'))),
  ];

  return {
    simulated: { iframeWidth: W, effectiveInnerWidth: win.innerWidth, effectiveInnerHeight: win.innerHeight },
    header: { clientWidth: header.clientWidth, scrollWidth: header.scrollWidth, overflowX: header.scrollWidth - header.clientWidth, rect: { left: +headerRect.left.toFixed(1), right: +headerRect.right.toFixed(1), w: +headerRect.width.toFixed(1) } },
    docOverflowX: doc.documentElement.scrollWidth - win.innerWidth,
    activeDS: dsSelect ? dsSelect.options[dsSelect.selectedIndex].text : null,
    amountUnit: amountSelect ? amountSelect.options[amountSelect.selectedIndex].text : null,
    items,
  };
}

