  const cs = (el) => win.getComputedStyle(el);
  const isVisible = (el) => { if (!el) return false; const c = cs(el); return c.display !== 'none' && c.visibility !== 'hidden' && el.getClientRects().length > 0; };
  const lineInfo = (el) => {
    const range = doc.createRange();
    range.selectNodeContents(el);
    const rects = Array.from(range.getClientRects());
    const tops = [...new Set(rects.map(r => Math.round(r.top)))].sort((a, b) => a - b);
    const groups = [];
    tops.forEach(t => { if (!groups.length || t - groups[groups.length - 1] > 2) groups.push(t); });
    return { lines: groups.length, textRects: rects.length };
  };
  const qa = (sel, root) => [...(root || header).querySelectorAll(sel)];
  const q = (sel, root) => (root || header).querySelector(sel);
  const info = (key, el, text) => {
    if (!el) return { key, found: false, visible: false };
    const vis = isVisible(el);
    const r = el.getBoundingClientRect();
    const out = {
      key, found: true, visible: vis, display: cs(el).display,
      rect: { left: +r.left.toFixed(1), right: +r.right.toFixed(1), w: +r.width.toFixed(1), h: +r.height.toFixed(1) },
